# Fermat's Factorization in Python
import gmpy2

def fermat_factor(n):
    a = gmpy2.isqrt(n) + 1
    while True:
        b2 = a * a - n
        b, exact = gmpy2.isqrt_rem(b2)
        if exact == 0 and b * b == b2:
            return int(a - b), int(a + b)
        a += 1

security_impact.detection_logic:
# YARA rule detecting ZIP archives appended after PNG IEND chunks
rule Stego_PNG_Appended_ZIP {
    strings:
        $png_iend = { 49 45 4E 44 AE 42 60 82 }
        $zip_header = { 50 4B 03 04 }
    condition:
        $png_iend at (filesize - [1000-500000]) and $zip_header
}

detection.yara:
rule XZ_Backdoor_Signature {
  meta:
    description = "Detects malicious payload inside liblzma.so"
    author = "CTF Atlas Threat Intel"
  strings:
    $op1 = { F3 0F 1E FA 55 48 89 E5 41 57 41 56 }
    $magic = { 43 7a 20 4c 5a 4d 41 }
  condition:
    uint32(0) == 0x464c457f and any of them
}

rule RegreSSHion_Payload_Pattern {
  meta:
    description = "Detects glibc heap grooming shellcode buffers"
  strings:
    $sc32 = { 31 c0 50 68 2f 2f 73 68 68 2f 62 69 6e 89 e3 50 53 89 e1 99 b0 0b cd 80 }
    $sc64 = { 48 31 f6 56 48 bf 2f 62 69 6e 2f 2f 73 68 57 48 89 e7 48 31 d2 48 31 c0 b0 3b 0f 05 }
  condition:
    any of them
}

rule RDLsvc_Heap_Exploit {
  meta:
    description = "Detects ASN.1 buffer overflow exploitation in RDLsvc"
  strings:
    $rpc_uuid = { d8 13 65 35 25 bb d0 11 a0 70 00 c0 4f b6 88 20 }
  condition:
    any of them
}

rule Triangulation_Binary_Implant {
  meta:
    description = "Detects Mach-O binaries utilizing undocumented Apple MMIO offsets"
  strings:
    $mmio_addr = { 00 20 01 08 02 }
    $sec_str = "AttachmentProcessor"
  condition:
    uint32(0) == 0xfeedfacf and any of them
}

rule EternalBlue_DoublePulsar_Ping {
  meta:
    description = "Detects DoublePulsar SMB ping response"
  strings:
    $s1 = { 53 4d 42 72 00 00 00 00 }
    $status = { 51 00 00 00 }
  condition:
    all of them
}

rule Heartbleed_Probe_Signature {
  meta:
    description = "Detects Heartbleed memory over-read exploit packets"
  strings:
    $hb = { 18 03 ?? ?? ?? 01 ff ff }
  condition:
    $hb at 0
}
